index 761f866..0c280c8 100644
--- a/sistema/sistema.cpp
+++ b/sistema/sistema.cpp
@@ -1993,6 +1993,163 @@ extern "C" void c_cedebug(natl id, const char *buf, natq quanti)
 //   ESAME 2024-01-10 )

 // ( SOLUZIONE 2024-01-10
+
+/**
+ * @brief Driver delle periferiche CE
+ *
+ * @param id	id della periferica CE
+ */
+extern "C" void c_driver_ce(natl id)
+{
+	if (id >= next_ce)
+		return;
+
+	des_ce *ce = &array_ce[id];
+
+	// Se non c'è una operazione in corso, disabilitiamo le interruzioni
+	// e usciamo subito
+	if (!ce->enabled) {
+		outputb(0, ce->iCTL);
+		return;
+	}
+
+	// Leggiamo un byte dal registro RBR
+	char byte = inputb(ce->iRBR);
+
+	// Controlliamo se c'è ancora qualcosa da leggere
+	if (ce->quanti == 0) {
+		// Operazione già completata, disabilitiamo le interruzioni
+		outputb(0, ce->iCTL);
+		return;
+	}
+
+	// Scriviamo il byte nel buffer
+	*ce->buf++ = byte;
+	ce->quanti--;
+
+	// Se abbiamo finito di leggere tutti i byte
+	if (ce->quanti == 0) {
+		// Disabilitiamo le interruzioni
+		outputb(0, ce->iCTL);
+		ce->enabled = false;
+		// Segnaliamo il completamento
+		sem_signal(ce->sync);
+	}
+}
+
+/**
+ * @brief Lettura di una sequenza di byte da una periferica CE, con timeout
+ *
+ * @param id		id della periferica
+ * @param buf		buffer destinato a contenere i byte letti
+ * @param[in,out] quanti	in: numero di byte da leggere, out: numero di byte effettivamente letti
+ * @param to		timeout
+ *
+ * @return 	true se l'operazione si è conclusa prima dello scatto del timeout, false altrimenti
+ */
+extern "C" void c_ceread_n_to(natl id, char *buf, natq& quanti, natl to)
+{
+	natl n;
+
+	// Controllo parametri
+	if (id >= next_ce) {
+		flog(LOG_WARN, "ceread_n_to: ce non valido: %u", id);
+		c_abort_p();
+		esecuzione->contesto[I_RAX] = 0;
+		return;
+	}
+
+	if (!to) {
+		flog(LOG_WARN, "ceread_n_to: timeout nullo");
+		c_abort_p();
+		esecuzione->contesto[I_RAX] = 0;
+		return;
+	}
+
+	// Ottengo il puntatore al riferimento quanti per validarne l'accesso
+	natq *quanti_ptr = &quanti;
+
+	// Controllo buffer nullo
+	if (buf == nullptr) {
+		flog(LOG_WARN, "ceread_n_to: buffer nullo");
+		c_abort_p();
+		esecuzione->contesto[I_RAX] = 0;
+		return;
+	}
+
+	// Controllo che il buffer sia nella regione utente/condivisa
+	if (!in_utn_c(int_cast<vaddr>(buf))) {
+		flog(LOG_WARN, "ceread_n_to: buffer non nella regione utente");
+		c_abort_p();
+		esecuzione->contesto[I_RAX] = 0;
+		return;
+	}
+
+	// Controllo Cavallo di Troia per il riferimento quanti
+	if (!c_access(int_cast<vaddr>(quanti_ptr), sizeof(natq), true, false)) {
+		flog(LOG_WARN, "ceread_n_to: quanti non valido");
+		c_abort_p();
+		esecuzione->contesto[I_RAX] = 0;
+		return;
+	}
+
+	// Ora posso leggere il valore di quanti in sicurezza
+	n = quanti;
+
+	if (n == 0) {
+		quanti = 0;
+		esecuzione->contesto[I_RAX] = 1;
+		return;
+	}
+
+	// Controllo Cavallo di Troia per il buffer di output
+	// Questo deve essere fatto dopo aver letto n, perché n potrebbe essere molto grande
+	if (!c_access(int_cast<vaddr>(buf), n, true, false)) {
+		flog(LOG_WARN, "ceread_n_to: buffer non scrivibile o non valido");
+		c_abort_p();
+		esecuzione->contesto[I_RAX] = 0;
+		return;
+	}
+
+	des_ce *ce = &array_ce[id];
+
+	// Acquisizione della mutua esclusione con timeout
+	if (sem_wait_to(ce->mutex, to) == 0) {
+		// Timeout durante l'acquisizione del mutex
+		flog(LOG_WARN, "ceread_n_to: timeout durante mutex");
+		quanti = 0;
+		esecuzione->contesto[I_RAX] = 0;
+		return;
+	}
+
+	// Impostiamo i dati per il trasferimento
+	ce->buf = buf;
+	ce->quanti = n;
+	ce->enabled = true;
+
+	// Abilitiamo le interruzioni sulla periferica
+	outputb(1, ce->iCTL);
+
+	// Attendiamo il completamento con timeout
+	natl result = sem_wait_to(ce->sync, to);
+
+	if (result == 0) {
+		// Timeout: annulliamo l'operazione
+		outputb(0, ce->iCTL);
+		ce->enabled = false;
+		quanti = n - ce->quanti;
+		sem_signal(ce->mutex);
+		flog(LOG_WARN, "ceread_n_to: timeout durante lettura");
+		esecuzione->contesto[I_RAX] = 0;
+		return;
+	}
+
+	// Operazione completata con successo
+	quanti = n;
+	sem_signal(ce->mutex);
+	esecuzione->contesto[I_RAX] = 1;
+	return;
+}
 //   SOLUZIONE 2024-01-10 )

