+a_ceread_n_to:
+	.cfi_startproc
+	.cfi_def_cfa_offset 40
+	.cfi_offset rip, -40
+	.cfi_offset rsp, -16
+	call salva_stato
+	call c_ceread_n_to
+	call carica_stato
+	iretq
+	.cfi_endproc
 //   SOLUZIONE 2024-01-10 )

 /// @addtogroup pgsyscall
@@ -1545,7 +1560,7 @@ access:
 	ret
 	.cfi_endproc

-	.global sem_wait_to
+.global sem_wait_to
 sem_wait_to:
 	.cfi_startproc
 	int $TIPO_WTO
@@ -1565,7 +1580,14 @@ abort_p:
 	int $TIPO_AB
 	ret
 	.cfi_endproc
-/// @endcond
+
+	.global ceread_n_to
+ceread_n_to:
+	.cfi_startproc
+	int $TIPO_CEREADTO
+	ret
+	.cfi_endproc
+/// @endcond
 //   ESAME 2024-01-10 )

